// lib/i18n/strings.dart
// Словарь интерфейса. Ключи плоские с точками. Сейчас RU + EN; ES/DE добавляются
// 1:1 в эту же карту (полный набор для 4 языков уже есть в HTML-прототипе).

class T {
  /// Поиск перевода с цепочкой фоллбэка: выбранный язык → английский → русский → сам ключ.
  /// Непереведённые строки нового языка показываются по-английски (международно), а не по-русски.
  static String of(String lang, String key) =>
      _m[lang]?[key] ?? _m['en']?[key] ?? _m['ru']![key] ?? key;

  // Глоссарий: порядок и длина задаются английским «мастер»-списком. Для каждого
  // термина берём перевод выбранного языка, иначе — английский (он полный). Так
  // новые термины сразу видны во всех языках, даже если их пока не перевели.
  static List<List<String>> gloss(String lang) {
    final master = _gloss['en'] ?? _gloss['ru']!;
    final loc = _gloss[lang] ?? const <List<String>>[];
    final out = <List<String>>[];
    for (var i = 0; i < master.length; i++) {
      out.add(i < loc.length ? loc[i] : master[i]);
    }
    return out;
  }

  // FAQ: список [вопрос, ответ] на язык; тот же пер-индексный фоллбэк lang → en.
  static List<List<String>> faq(String lang) {
    final master = _faq['en'] ?? _faq['ru']!;
    final loc = _faq[lang] ?? const <List<String>>[];
    final out = <List<String>>[];
    for (var i = 0; i < master.length; i++) {
      out.add(i < loc.length ? loc[i] : master[i]);
    }
    return out;
  }

